        guideImages:L(['guides/lg-fy9wtb-use-01-ko.webp','guides/lg-fy9wtb-use-02-ko.webp','guides/lg-fy9wtb-use-03-ko.webp'], ["guides/washer-quick-en-v67.svg"], ["guides/washer-quick-ja-v67.svg"], ["guides/washer-quick-zh-v67.svg"], ["guides/washer-quick-zh-TW-v67.svg"]),
