        guideImages:L(['guides/microwave-panel-ko.svg'], ["guides/microwave-panel-en.svg"], ["guides/microwave-panel-ja.svg"], ["guides/microwave-panel-zh.svg"], ["guides/microwave-panel-zh-TW.svg"]),
